# hypothesis: PEP 695 infers covariance for a read-only generic and invariance for one with a setter, so Holder[int] is rejected where Holder[float] is expected.
from typing import assert_type


class Reader[T]:
    def __init__(self, item: T) -> None:
        self._item = item

    def get(self) -> T:
        return self._item


class Holder[T]:
    def __init__(self, item: T) -> None:
        self.item = item

    def set(self, item: T) -> None:
        self.item = item

    def get(self) -> T:
        return self.item


class Shape:
    def area(self) -> float:
        return 0.0


class Square(Shape):
    def __init__(self, side: float) -> None:
        self.side = side

    def area(self) -> float:
        return self.side * self.side


def largest[S: Shape](shapes: list[S]) -> S:
    return max(shapes, key=lambda s: s.area())


def read_float(r: Reader[float]) -> float:
    return r.get()


def reject_invariant(h: Holder[int]) -> Holder[float]:
    return h  # expect-error: Holder is invariant in T


def reject_bound() -> str:
    try:
        largest([1, 2])  # expect-error: int does not satisfy bound Shape
    except AttributeError:
        return 'rejected'
    return 'accepted'


ints = Reader(3)
assert_type(ints, Reader[int])
assert read_float(ints) == 3
assert_type(largest([Square(2.0), Square(1.0)]), Square)
assert largest([Square(2.0), Square(1.0)]).side == 2.0
holder = Holder(1)
holder.set(2)
assert holder.get() == 2
assert reject_invariant(holder) is holder
assert reject_bound() == 'rejected'
